INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, texto_completo, raw_content, costo, action_url, url_fuente) VALUES (2101, 'Inscribirte como empleador de un trabajador del hogar', 'https://www.gob.pe/12546-inscribirte-como-empleador-de-un-trabajador-del-hogar', 'SUNAT', 'Inscribirte como empleador de un trabajador del hogar Servicio inhabilitado desde el  8 de diciembre de 2021 Este trámite lo debes realizar a través de la plataforma "Registro del Trabajo del Hogar" desarrollado por el Ministerio de Trabajo y Promoción del Empleo, de acuerdo a lo establecido en la Resolución Ministerial N° 243-2021-TR. Si contratas a un(a) trabajador(a) del hogar , debes inscribirte como su empleador. Modalidad: Online Antes de iniciar, debes saber: Ingresa a la plataforma "Registro del Trabajo del Hogar" desarrollado por el Ministerio de Trabajo y Promoción del Empleo Último cambio  01 setiembre 2023', 'Inscribirte como empleador de un trabajador del hogar Servicio inhabilitado desde el  8 de diciembre de 2021 Este trámite lo debes realizar a través de la plataforma "Registro del Trabajo del Hogar" desarrollado por el Ministerio de Trabajo y Promoción del Empleo, de acuerdo a lo establecido en la Resolución Ministerial N° 243-2021-TR. Si contratas a un(a) trabajador(a) del hogar , debes inscribirte como su empleador. Modalidad: Online Antes de iniciar, debes saber: Ingresa a la plataforma "Registro del Trabajo del Hogar" desarrollado por el Ministerio de Trabajo y Promoción del Empleo Último cambio  01 setiembre 2023', '', '', 'https://www.gob.pe/12546-inscribirte-como-empleador-de-un-trabajador-del-hogar');
INSERT OR REPLACE INTO tramites_fts (rowid, titulo_oficial, texto_completo) VALUES (2101, 'Inscribirte como empleador de un trabajador del hogar', 'Inscribirte como empleador de un trabajador del hogar Servicio inhabilitado desde el  8 de diciembre de 2021 Este trámite lo debes realizar a través de la plataforma "Registro del Trabajo del Hogar" desarrollado por el Ministerio de Trabajo y Promoción del Empleo, de acuerdo a lo establecido en la Resolución Ministerial N° 243-2021-TR. Si contratas a un(a) trabajador(a) del hogar , debes inscribirte como su empleador. Modalidad: Online Antes de iniciar, debes saber: Ingresa a la plataforma "Registro del Trabajo del Hogar" desarrollado por el Ministerio de Trabajo y Promoción del Empleo Último cambio  01 setiembre 2023');
INSERT OR REPLACE INTO tramites (id, titulo_oficial, url, entidad, texto_completo, raw_content, costo, action_url, url_fuente) VALUES (2102, 'Recibir orientación tributaria o aduanera', 'https://www.gob.pe/9122-recibir-orientacion-tributaria-o-aduanera', 'SUNAT', 'Recibir orientación tributaria o aduanera Si tienes alguna consulta tributaria y/o aduanera, puedes realizarla a través de los canales de atención que Sunat tiene disponibles: Modalidad: Online Canales online: Chat tributario e informático: atiende consultas escritas de manera instantánea para recibir orientación tributaria e informática de carácter general.  Su horario es de lunes a viernes de 8:30 a. m. a 6:00 p. m. Consultas tributarias Consultas informáticas Chat aduanero : atiende consultas escritas de manera instantánea para recibir orientación aduanera de carácter general. Su horario es de lunes a viernes de 8:30 a. m. a 4:30 p. m. Facebook Sunat : atiende consultas de carácter general sobre los procedimientos y normas en materia tributaria y aduanera, tanto para personas naturales como empresas. Asistente virtual Sofía : el Servicio de Orientación y Facilitación de Información Automatizada te orienta sobre trámites tributarios, temas de cobranza coactiva, temas aduaneros, tus obligaciones mensuales y renta anual 2020 como persona natural. Además, cuenta con videotutoriales que te servirán de guía para el cumplimiento oportuno de tus obligaciones tributarias. Consultas aduaneras: atiende consultas relacionadas de temas aduaneros como régimen de importación, exportación, admisión temporal, reglamento de equipajes y menaje de casa, incentivos migratorios, exporta fácil y otros. También puedes hacerlo por teléfono: Modalidad: Teléfono Puedes llamar a la Central de Consultas para dudas de temas tributarios, aduaneros e informáticos, de lunes a viernes de 8:30 a. m. a 6:00 p. m. a los siguientes números: Desde celulares y teléfonos fijos: (01) 315 0730 Desde teléfonos fijos a nivel nacional: 0 801 12 100 Último cambio  02 julio 2025', 'Recibir orientación tributaria o aduanera Si tienes alguna consulta tributaria y/o aduanera, puedes realizarla a través de los canales de atención que Sunat tiene disponibles: Modalidad: Online Canales online: Chat tributario e informático: atiende consultas escritas de manera instantánea para recibir orientación tributaria e informática de carácter general.  Su horario es de lunes a viernes de 8:30 a. m. a 6:00 p. m. Consultas tributarias Consultas informáticas Chat aduanero : atiende consultas escritas de manera instantánea para recibir orientación aduanera de carácter general. Su horario es de lunes a viernes de 8:30 a. m. a 4:30 p. m. Facebook Sunat : atiende consultas de carácter general sobre los procedimientos y normas en materia tributaria y aduanera, tanto para personas naturales como empresas. Asistente virtual Sofía : el Servicio de Orientación y Facilitación de Información Automatizada te orienta sobre trámites tributarios, temas de cobranza coactiva, temas aduaneros, tus obligaciones mensuales y renta anual 2020 como persona natural. Además, cuenta con videotutoriales que te servirán de guía para el cumplimiento oportuno de tus obligaciones tributarias. Consultas aduaneras: atiende consultas relacionadas de temas aduaneros como régimen de importación, exportación, admisión temporal, reglamento de equipajes y menaje de casa, incentivos migratorios, exporta fácil y otros. También puedes hacerlo por teléfono: Modalidad: Teléfono Puedes llamar a la Central de Consultas para dudas de temas tributarios, aduaneros e informáticos, de lunes a viernes de 8:30 a. m. a 6:00 p. m. a los siguientes números: Desde celulares y teléfonos fijos: (01) 315 0730 Desde teléfonos fijos a nivel nacional: 0 801 12 100 Último cambio  02 julio 2025', '', '', 'https://www.gob.pe/9122-recibir-orientacion-tributaria-o-aduanera');
